using System;
using System.Net;
using System.Net.Http;
using System.Threading.Tasks;

public class MockTestServer
{
    public HttpResponseMessage SimulateRequest(string method, string path, string? jsonBody)
    {
        if (path == "/api/v1/orders" && method == "POST")
        {
            if (string.IsNullOrWhiteSpace(jsonBody))
            {
                return new HttpResponseMessage(HttpStatusCode.BadRequest);
            }

            return new HttpResponseMessage(HttpStatusCode.Created);
        }

        return new HttpResponseMessage(HttpStatusCode.NotFound);
    }
}

public class Program
{
    public static void Main()
    {
        var server = new MockTestServer();

        var resp1 = server.SimulateRequest("POST", "/api/v1/orders", null);
        Console.WriteLine($"Test 1 (Empty Body) -> Status: {resp1.StatusCode} (Ekspektasi: BadRequest)");

        var resp2 = server.SimulateRequest("POST", "/api/v1/orders", "{\"item\":\"Laptop\"}");
        Console.WriteLine($"Test 2 (Valid Body) -> Status: {resp2.StatusCode} (Ekspektasi: Created)");
    }
}
